mapper.select:
SELECT ud.id, ud.user_id, ud.dept_id, d.dept_name, d.dept_code, ud.is_primary, ud.status, ud.create_time, ud.update_time, ud.create_user, ud.update_user, ud.version, ud.remark FROM user_dept ud INNER JOIN sys_dept d ON d.id = ud.dept_id AND d.is_deleted = 0 WHERE ud.user_id = #{userId}
AND d.dept_name LIKE CONCAT('%', #{query.deptName}, '%')
AND d.dept_code LIKE CONCAT('%', #{query.deptCode}, '%')
AND ud.status = #{query.status}
ORDER BY ud.is_primary DESC, ud.create_time DESC, ud.id DESC
